CREATE TABLE "Asset" ("id" TEXT NOT NULL,"novelId" TEXT NOT NULL,"originalName" TEXT NOT NULL,"storedName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Asset_pkey" PRIMARY KEY ("id"));
CREATE TABLE "StickyNote" ("id" TEXT NOT NULL,"novelId" TEXT NOT NULL,"chapterId" TEXT,"body" TEXT NOT NULL DEFAULT '',"color" TEXT NOT NULL DEFAULT 'yellow',"positionX" INTEGER NOT NULL DEFAULT 40,"positionY" INTEGER NOT NULL DEFAULT 40,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StickyNote_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Asset_storedName_key" ON "Asset"("storedName"); CREATE INDEX "Asset_novelId_createdAt_idx" ON "Asset"("novelId","createdAt"); CREATE INDEX "StickyNote_novelId_updatedAt_idx" ON "StickyNote"("novelId","updatedAt"); CREATE INDEX "StickyNote_chapterId_idx" ON "StickyNote"("chapterId");
ALTER TABLE "Asset" ADD CONSTRAINT "Asset_novelId_fkey" FOREIGN KEY ("novelId") REFERENCES "Novel"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StickyNote" ADD CONSTRAINT "StickyNote_novelId_fkey" FOREIGN KEY ("novelId") REFERENCES "Novel"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "StickyNote" ADD CONSTRAINT "StickyNote_chapterId_fkey" FOREIGN KEY ("chapterId") REFERENCES "Chapter"("id") ON DELETE SET NULL ON UPDATE CASCADE;